-- Convert every DateTime column from timestamp(3) (naive, always written as UTC by Prisma)
-- to timestamptz(3). USING ... AT TIME ZONE 'UTC' pins the conversion to UTC so every
-- existing value keeps the same instant, regardless of the session TimeZone the
-- migration happens to run under.

ALTER TABLE "Shop" ALTER COLUMN "createdAt" SET DATA TYPE TIMESTAMPTZ(3) USING "createdAt" AT TIME ZONE 'UTC';
ALTER TABLE "Shop" ALTER COLUMN "updatedAt" SET DATA TYPE TIMESTAMPTZ(3) USING "updatedAt" AT TIME ZONE 'UTC';
ALTER TABLE "ShopWorkingSchedule" ALTER COLUMN "startDate" SET DATA TYPE TIMESTAMPTZ(3) USING "startDate" AT TIME ZONE 'UTC';
ALTER TABLE "ShopWorkingSchedule" ALTER COLUMN "endDate" SET DATA TYPE TIMESTAMPTZ(3) USING "endDate" AT TIME ZONE 'UTC';
ALTER TABLE "ShopWorkingSchedule" ALTER COLUMN "createdAt" SET DATA TYPE TIMESTAMPTZ(3) USING "createdAt" AT TIME ZONE 'UTC';
ALTER TABLE "ShopWorkingSchedule" ALTER COLUMN "updatedAt" SET DATA TYPE TIMESTAMPTZ(3) USING "updatedAt" AT TIME ZONE 'UTC';
ALTER TABLE "UserShop" ALTER COLUMN "createdAt" SET DATA TYPE TIMESTAMPTZ(3) USING "createdAt" AT TIME ZONE 'UTC';
ALTER TABLE "Service" ALTER COLUMN "createdAt" SET DATA TYPE TIMESTAMPTZ(3) USING "createdAt" AT TIME ZONE 'UTC';
ALTER TABLE "Service" ALTER COLUMN "updatedAt" SET DATA TYPE TIMESTAMPTZ(3) USING "updatedAt" AT TIME ZONE 'UTC';
ALTER TABLE "StaffService" ALTER COLUMN "createdAt" SET DATA TYPE TIMESTAMPTZ(3) USING "createdAt" AT TIME ZONE 'UTC';
ALTER TABLE "User" ALTER COLUMN "createdAt" SET DATA TYPE TIMESTAMPTZ(3) USING "createdAt" AT TIME ZONE 'UTC';
ALTER TABLE "User" ALTER COLUMN "updatedAt" SET DATA TYPE TIMESTAMPTZ(3) USING "updatedAt" AT TIME ZONE 'UTC';
