ALTER TABLE "Booking" ALTER COLUMN "endTime" SET DATA TYPE TIMESTAMPTZ(3) USING "endTime" AT TIME ZONE 'UTC';
ALTER TABLE "Booking" ALTER COLUMN "createdAt" SET DATA TYPE TIMESTAMPTZ(3) USING "createdAt" AT TIME ZONE 'UTC';
ALTER TABLE "Booking" ALTER COLUMN "updatedAt" SET DATA TYPE TIMESTAMPTZ(3) USING "updatedAt" AT TIME ZONE 'UTC';
